data_font = Font(name="Arial", size=10)
wrap_align = Alignment(wrap_text=True, vertical="top")
trickster_fill = PatternFill("solid", start_color="FFF2CC")

for row_idx, verse in enumerate(verses, 2):
    has_trickster = bool(verse[5])
    for col_idx, val in enumerate(verse, 1):
        cell = ws.cell(row=row_idx, column=col_idx, value=val)
        cell.font = data_font
        cell.alignment = wrap_align
        if has_trickster:
            cell.fill = trickster_fill

col_widths = [40, 40, 45, 55, 55, 75]
for col_idx, width in enumerate(col_widths, 1):
    ws.column_dimensions[get_column_letter(col_idx)].width = width

ws.row_dimensions[1].height = 30
ws.freeze_panes = "A2"

thin = Side(style='thin', color="CCCCCC")
border = Border(left=thin, right=thin, top=thin, bottom=thin)
for row in ws.iter_rows(min_row=1, max_row=len(verses)+1, min_col=1, max_col=6):
    for cell in row:
        cell.border = border

wb.save("/mnt/user-data/outputs/kalevala_runo10.xlsx")
print(f"Done. {len(verses)} verses processed.")
